from functools import cmp_to_key


def _parse(v):
    before_plus = v.split('+', 1)[0]
    if '-' in before_plus:
        core, pre = before_plus.split('-', 1)
        pre_list = pre.split('.')
    else:
        core = before_plus
        pre_list = None
    parts = core.split('.')
    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
    return (major, minor, patch, pre_list)


def _compare_prerelease(pre1, pre2):
    for a, b in zip(pre1, pre2):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai != bi:
                return -1 if ai < bi else 1
        elif a_num and not b_num:
            return -1
        elif not a_num and b_num:
            return 1
        else:
            if a != b:
                return -1 if a < b else 1
    if len(pre1) != len(pre2):
        return -1 if len(pre1) < len(pre2) else 1
    return 0


def _compare(p1, p2):
    major1, minor1, patch1, pre1 = p1
    major2, minor2, patch2, pre2 = p2

    if major1 != major2:
        return -1 if major1 < major2 else 1
    if minor1 != minor2:
        return -1 if minor1 < minor2 else 1
    if patch1 != patch2:
        return -1 if patch1 < patch2 else 1

    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None:
        return 1
    if pre2 is None:
        return -1
    return _compare_prerelease(pre1, pre2)


def semver_sort(versions):
    parsed = [(_parse(v), v) for v in versions]
    parsed_sorted = sorted(parsed, key=cmp_to_key(lambda a, b: _compare(a[0], b[0])))
    return [v for _, v in parsed_sorted]

